/**
 * 톡사르 그레이딩 테마 데이터.
 *
 * 톡사르는 **발밑이 오염 웅덩이라 아래가 빛나고 위는 두꺼운 독무에 덮여 있다.** 아래 값들은
 * 그 한 문장의 결과다 — 비네트 코어를 아래로 내려 독무 낀 하늘을 더 누르고, 하단 가산은
 * 웅덩이 반사광이며, 곱연산은 상단·좌우에 둔다.
 *
 * ## 스플릿 톤 방향이 카르곤과 **반대**다 (`warmthDirection: -1`)
 * 이 축은 취향이 아니라 광원 색의 귀결이다. 톡사르의 유일한 광원이 자홍 개천이라 **빛이
 * 닿는 곳(하이라이트)은 B 가 지배**하고, 빛이 안 닿는 곳은 부패한 유기물의 적갈이 남는다.
 * 카르곤(주황 용암 → 하이라이트가 따뜻함)과 정확히 뒤집힌 물리다.
 *
 * 부호를 코드에 `+1` 로 박았다면 이 행성의 단조성 검사가 통째로 뒤집혀 "스플릿이 없다"로
 * 오판됐을 자리이며, 그래서 `WarmthDirection` 이 테마 필드다.
 *
 * ## 알파 6개는 하나의 예산이다 — 실제 배분
 * `gain` 이 색온도 분리를 떠맡는데 톡사르 gain 틴트(0xa0b8ff)는 휘도 0.722 라 카르곤의
 * 0xffdcae(0.879)보다 **훨씬 비싸다**(감쇠 0.2784 vs 0.121). 그래서 gain 알파를 카르곤의
 * 0.30 → **0.18** 로 내려야 중앙 잔존율이 산다:
 *
 * | 항목 | 값 | 한도 |
 * |---|---|---|
 * | 중앙 안전영역 감쇠(= gain 항뿐) | 0.18 × 0.2784 = 0.0501 | 잔존율 0.9499 ≥ 0.94 |
 * | 가장자리 최대 감쇠 | 0.2381(비네트) + 0.0308(cool) + 0.0501(gain) = **0.3190** | ≤ 0.36 |
 * | 암부 휘도 상승(lift) | 0.04 × 0.2575 = 0.0103 | ≤ 0.06 |
 * | warmth 부호 교차점 | 0.5966 | (0,1) 안 |
 *
 * `cool` 상단 램프를 −0.4 에서 시작하는 것도 이 예산 때문이다 — 카르곤(−0.2)처럼 두면
 * 중앙 안전영역(|ny| ≤ 0.35) 안까지 램프가 들어와 잔존율이 0.94 밑으로 떨어진다.
 */

import type { GradeTheme } from '../../contracts/grade.js';

export const TOXAR_GRADE: GradeTheme = {
  themeId: 'toxar',
  alpha: {
    // 현대 AAA 비네트의 통상 대역(20~40%) 안쪽. gain 이 비싼 만큼 카르곤(0.28)보다 낮췄다.
    vignette: 0.24,
    /** 하단 웅덩이 반사광. 국소 근거가 있는 최소량만 — 전역 색온도는 gain 이 맡는다. */
    warm: 0.05,
    /** 가장자리 **형상** 담당. 전역 톤은 gain 이 가져갔으므로 이만큼이면 된다. */
    cool: 0.05,
    /** 위 표 참조 — 틴트 휘도가 비싸 카르곤의 상한(0.3)을 쓸 수 없다. */
    gain: 0.18,
    /** 더 키우면 R 채널이 흰색에서 오버플로한다(여유가 정확히 0.0671 이다). */
    shadow: 0.04,
    // 밴딩을 깨는 최소량. 이 이상은 화면이 지저분해진다.
    grain: 0.032,
  },
  /** 코어를 아래로 내려 독무 낀 위쪽을 더 누른다. `outer` 는 최원거리 모서리가 거의 최대에 닿는 값. */
  vignette: { centerY: 0.12, inner: 0.62, outer: 1.55 },
  /** 화면 **하단 1/4** 밖으로는 한 픽셀도 밝히지 않는다(시차 레이어와의 중복 해소). */
  warm: { startY: 0.42, sideFalloff: 0.42 },
  /** 상단 램프가 −0.4 부터인 이유는 위 예산표 마지막 문단에 있다. */
  cool: { topStart: -0.4, topEnd: -1, sideStart: 0.68, sideEnd: 1.08 },
  tint: {
    /** 웅덩이 반사광 계열 자홍(297.1°) — 배경 팔레트와 같은 골짜기에 있다. */
    warm: 0xd83ce0,
    /** 늪 그늘의 암록. 하이라이트(청자)와 색상을 가른다. */
    cool: 0x4a6a58,
    /** 무채에 가깝게 두어 색을 밀지 않는다. */
    grain: 0xb0b8c0,
    /**
     * 하이라이트 청자. B=255 라 흰 화소의 B 손실이 0 이고, 그래서 g=1 에서 B 채널의
     * 오버플로 여유가 정확히 0 인 채 등호에 붙는다(카르곤이 R 에서 겪은 경계 사례의 거울상).
     * R 을 160 까지 낮춘 만큼이 스플릿의 기울기다.
     */
    gain: 0xa0b8ff,
    /**
     * 암부 적갈. G=16·B=0 인 순적 계열을 고른 이유는 **채도 대비 휘도가 싸기** 때문이다 —
     * R−B 를 255 나 벌리면서 휘도는 0.2575 밖에 안 올라 lift 예산을 거의 안 먹는다.
     */
    shadow: 0xff1000,
  },
  /** 자홍 개천이 광원이므로 하이라이트가 차갑고 암부가 따뜻하다 — 카르곤과 반대다. */
  warmthDirection: -1,
};
